INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-01','Oscilloscope: No Trace on Screen','Easy','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','You connect a signal to an oscilloscope but see no trace. The most likely first thing to check is:','{"choices": ["The signal frequency exceeds 1 GHz", "Trigger, timebase, and voltage scale settings — the trace may be present but off-screen or trigger is not firing", "The oscilloscope is broken", "The probe bandwidth is insufficient"], "correct": 1}'::jsonb,'No trace is almost always a settings issue: (1) Trigger level not in signal range, (2) timebase too fast or slow, (3) voltage/division too large (signal appears flat near 0). Always check trigger, then scale.','{multiple_choice}'::text[],0.85) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-02','Multimeter: Reading Infinity (OL) on Resistance','Easy','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','A multimeter reads OL (overflow / infinity) when measuring a resistor. The most likely cause is:','{"choices": ["The resistor has zero resistance (short)", "The resistor is open-circuited, the range is too low, or the resistor value exceeds the selected range", "The battery is dead", "DC and AC modes are mixed up"], "correct": 1}'::jsonb,'OL (Over Limit) = open circuit or range exceeded. If the resistor should be 100 kΩ but range is 10 kΩ → switch to higher range. An actual OL at any range means open circuit (broken resistor or no connection).','{multiple_choice}'::text[],0.88) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-03','Power Supply: Voltage Drops Under Load','Easy','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','A bench power supply shows 12 V with no load, but voltage drops to 9 V when a 1 A load is connected. Likely cause:','{"choices": ["The load is drawing too much current", "High internal resistance of the supply or a poor connection — voltage drop = I × R_internal = 1 × 3 Ω = 3 V", "The power supply is a switching type", "The voltmeter is inaccurate"], "correct": 1}'::jsonb,'Voltage drop under load = I × R_internal. Here 3 V drop at 1 A → R_internal = 3 Ω (too high for a bench supply, should be < 0.1 Ω). Check current limit setting, output fuse, sense wires, and supply specifications.','{multiple_choice}'::text[],0.82) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-04','PCB: Missing Power Net Short Investigation','Easy','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','After PCB assembly, the 3.3 V power rail measures 0 Ω to GND (dead short). First diagnostic step:','{"choices": ["Replace the voltage regulator", "Desolder the voltage regulator output and check if short disappears — systematically remove/disconnect power consumers to locate the short to ground", "Reflow the entire board", "Check decoupling capacitors with an oscilloscope"], "correct": 1}'::jsonb,'Systematic isolation: remove power source → check raw rail to GND. If short: disconnect load ICs one by one (or heat with thermal camera) to find shorted component. Tantalum caps and reverse-mounted diodes are common culprits.','{multiple_choice}'::text[],0.78) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-05','Soldering: Cold Solder Joint Identification','Easy','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','A PCB has an intermittent connection that works when pressed. Visual inspection shows a dull, grainy solder joint. This is most likely:','{"choices": ["A correct solder joint", "A short circuit between adjacent pads", "A cold solder joint — insufficient heat during soldering causes incomplete tin-lead or SAC alloy bonding, resulting in high resistance or intermittent connection", "Excess flux residue"], "correct": 2}'::jsonb,'Cold joints are caused by insufficient soldering iron temperature, short dwell time, or contamination. Shiny joints (SnPb) or semi-matte (SAC lead-free) are good. Dull/grainy = cold. Fix: reheat with fresh flux and solder.','{multiple_choice}'::text[],0.84) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-06','Op-Amp Circuit: Oscillating Output','Medium','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','An op-amp circuit oscillates at a high frequency (MHz range) with no input signal. Probable cause(s):','{"choices": ["The gain is too low", "The op-amp is damaged", "Insufficient phase margin (feedback factor too high, long PCB traces creating parasitic feedback, or no compensation capacitor) — op-amp becomes unstable and self-oscillates", "Power supply voltage is too high"], "correct": 2}'::jsonb,'Op-amp oscillation at RF is almost always stability-related: excess phase shift in feedback loop at high frequency causes positive feedback. Fix: add small capacitor in feedback (dominant pole compensation), shorten PCB traces, add series resistor on output.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-07','Microcontroller: GPIO Not Toggling','Medium','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','An oscilloscope shows no activity on a GPIO expected to toggle at 1 Hz. The MCU appears powered. Systematic debug order:','{"choices": ["Replace the microcontroller", "Check code is actually running (use LED heartbeat/UART debug), verify GPIO is configured as output and correct pin, check clock and peripheral enable registers", "Check the oscilloscope probe", "Increase power supply voltage"], "correct": 1}'::jsonb,'Systematic debug: (1) Verify MCU is running (heartbeat LED or UART). (2) Check pin configuration in firmware (direction register, alternate function, peripheral clock enable). (3) Check physical connection — probe on correct net. Never replace components before verifying software.','{multiple_choice}'::text[],0.76) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-08','Switching Regulator: High Output Ripple','Medium','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','A buck converter output has excessive voltage ripple (200 mV peak-to-peak instead of designed 50 mV). Most likely cause:','{"choices": ["Input voltage is too high", "Switching frequency is too low", "Output capacitor ESR is too high, capacitor is wrong type, or capacitance is below design value — ESR contributes directly to output ripple", "The inductor is oversized"], "correct": 2}'::jsonb,'Output ripple V_ripple ≈ I_ripple × ESR (for high-frequency ripple). High ESR (e.g., electrolytic at frequency) or wrong capacitor type (electrolytic instead of ceramic) causes excess ripple. Verify capacitor specs and measure with scope in AC-coupled mode.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-09','UART Communication Failure: Garbled Data','Medium','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','UART communication between two devices produces garbled/random characters. Both are set to 115200 baud. Most likely cause:','{"choices": ["The cable is too long", "Baud rate mismatch (even small differences cause bit sampling errors), incorrect stop bits, or parity mismatch between devices", "The UART peripheral needs to be reset", "Voltage difference between devices"], "correct": 1}'::jsonb,'Garbled UART is almost always baud rate mismatch — even 1% error can accumulate to misalign bit sampling. Check both sides: baud rate, data bits (8 vs 7), parity (None/Even/Odd), stop bits (1 vs 2). Also check TX→RX wiring (not TX→TX).','{multiple_choice}'::text[],0.74) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-10','I²C Bus: NACK on Every Transaction','Medium','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','An I²C master sends a command but receives NACK on every transaction. The slave device should respond at address 0x68. Debug steps (in order):','{"choices": ["Replace the I²C slave device", "Verify pull-up resistors on SDA/SCL, confirm slave address (check A0/A1/A2 pins), verify slave power supply, check I²C scan with master", "Increase I²C clock speed", "Use SPI instead of I²C"], "correct": 1}'::jsonb,'NACK = slave not acknowledging. Root causes: wrong address (address pins floating?), missing pull-ups (SDA/SCL stuck at 0?), slave not powered, bus stuck in error state. Run an I²C scanner to detect actual addresses on the bus.','{multiple_choice}'::text[],0.7) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-11','ADC Readings: Noise and Drift','Medium','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','ADC readings fluctuate ±50 counts (out of 4096) even with a stable DC input. Likely causes (select most likely):','{"choices": ["ADC reference voltage is too high", "Power supply noise coupling into AVCC/VREF, missing analog ground plane, or excessive digital switching noise — decouple AVCC with 100 nF + 10 µF; separate AGND from DGND at star point", "ADC gain is set too high", "Sample rate is too high"], "correct": 1}'::jsonb,'ADC noise floor is strongly influenced by power supply noise. 50-count noise on a 12-bit ADC = 50/4096 = 1.2% = ~12 mV on 1 V reference. Fix: low-noise LDO for AVCC, careful PCB layout (analog ground island), input RC filter.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-12','Motor Driver: Overtemperature Shutdown','Medium','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','A motor driver IC repeatedly shuts down due to overtemperature. The motor specification is within the driver''s rated current. Most likely cause:','{"choices": ["Motor is defective", "Ambient temperature is normal", "Inadequate heatsinking/thermal path, PWM frequency too low causing high switching losses, or motor has higher winding resistance than expected causing excess I²R heating", "Current sense resistor is wrong"], "correct": 2}'::jsonb,'Driver shutdown means T_J is exceeding T_J(max). Causes: PCB copper area insufficient (θ_JA too high), PWM at low frequency → high switching losses, motor stall (locked rotor = maximum current), or thermal runaway with no heatsink. Measure case temperature.','{multiple_choice}'::text[],0.66) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-13','RF Amplifier: Low Output Power','Hard','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','An RF power amplifier''s output power is 3 dB below specification. The bias current is correct. Probable causes to investigate:','{"choices": ["The amplifier is too linear", "Input power is insufficient (gain is correct — check source), impedance mismatch (50 Ω nominal not achieved), or output filter has excessive insertion loss", "The power supply is 0.1 V above nominal", "The frequency is slightly off"], "correct": 1}'::jsonb,'3 dB low output: (1) Check input drive level — if gain is spec, P_out = P_in + Gain; low P_in → low P_out. (2) SWR measurement: impedance mismatch causes power reflection. (3) Output matching network loss. Use a power meter and VNA.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-14','EMC Failure: Radiated Emissions','Hard','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','A product fails CE/FCC radiated emissions testing. The strongest emission is at 168 MHz. The MCU runs at 168 MHz. Most likely cause and fix:','{"choices": ["The MCU clock is too fast — reduce frequency", "High-speed clock traces acting as antennas — add ferrite beads on clock lines, improve PCB ground plane, add spread spectrum clocking, reduce clock trace length and termination", "Add more decoupling capacitors everywhere", "Shield the entire PCB with a metal can"], "correct": 1}'::jsonb,'Emissions at exactly the CPU clock frequency (168 MHz) = clock radiation. Fix: (1) Spread spectrum dithering on PLL to spread energy across frequencies, (2) shorter/shielded clock traces, (3) proper ground plane reduces antenna efficiency, (4) π-filter on clock output.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-15','Digital Circuit: Random Resets','Hard','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','An embedded system randomly resets without apparent cause. Frequency increases under heavy load. Differential diagnosis:','{"choices": ["The firmware has an infinite loop", "Power supply brownout (voltage sag under load triggering brown-out detect), watchdog timer not being serviced, or stack overflow corrupting reset vector — log reset cause register on startup", "The clock crystal is loose", "The JTAG debugger is interfering"], "correct": 1}'::jsonb,'Random resets under load strongly suggest power supply issues (brownout detect). Check: voltage at MCU VCC pin under load (oscilloscope, AC-coupled), brown-out threshold setting, reset cause register. Also check watchdog if timer-based and stack depth with linker map.','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-16','Sensor: Incorrect Readings at Power-On','Hard','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','A temperature sensor reads −40°C at power-on, then gradually reaches the correct value over 30 seconds. The most likely cause:','{"choices": ["The sensor is damaged", "The ADC reference is drifting", "Thermal self-heating of the sensor PCB from cold start, insufficient power supply settling time, or the sensor needs a warm-up period per datasheet", "I²C clock speed is too slow"], "correct": 2}'::jsonb,'Temperature sensors are sensitive to thermal gradients. At power-on, the PCB is at ambient but the sensor substrate (and internal self-heating) hasn''t equilibrated. Also check: datasheet power-on time, supply ramp time meeting spec, and thermal mass of the PCB.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-17','Memory: Bit Flip Analysis','Hard','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','An embedded system experiences occasional single-bit data corruption in RAM. The system operates near high-voltage equipment. Most likely cause:','{"choices": ["Software bug — unintialised variables", "Electrical overstress from nearby equipment causing single-event upsets (SEU), or insufficient ECC memory — single bit flips can indicate cosmic ray SEU or electrical noise coupling", "Clock domain crossing issue", "Stack overflow"], "correct": 1}'::jsonb,'Single-bit flips in RAM near HV equipment: suspect conducted/radiated noise causing bit flips. In high-reliability systems: ECC RAM detects/corrects single-bit errors. Shielding, filtering on power and I/O, and watchdog/CRC checks on critical data are mitigation.','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-18','Wireless Module: Low Range','Hard','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','A 2.4 GHz Bluetooth module achieves only 1/4 of its rated range. The antenna is correctly specified. Debug approach:','{"choices": ["Use a higher gain antenna without regulatory approval", "Verify RF output power (use spectrum analyser), check antenna impedance match (S11 with VNA), ensure antenna clearance from PCB ground plane and metal, check RF cable/connector losses", "Increase transmit power in firmware", "Switch to 5 GHz band"], "correct": 1}'::jsonb,'1/4 range = ~6 dB less. Causes: antenna mismatch (reflected power), ground plane under antenna (detuning), nearby metal, RF cable loss. Use spectrum analyser to verify TX power; VNA to verify S11 < −10 dB at 2.4 GHz at the antenna input.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-19','Oscilloscope Probe Loading Effect','Hard','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','When probing a high-impedance node with a 1× oscilloscope probe, the measured signal changes significantly (waveform distorted, frequency shifts). This is caused by:','{"choices": ["Probe bandwidth is too low", "Probe ground lead inductance", "Probe loading — 1× probe adds ~100 pF capacitance to the circuit node, significantly changing the RC time constant at high frequencies. Use 10× probe (10 MΩ, ~15 pF) for high-impedance nodes", "Oscilloscope input impedance is too low"], "correct": 2}'::jsonb,'1× probe: 1 MΩ in parallel with ~100 pF. At 1 MHz, 100 pF = 1.6 kΩ reactance — drastically loads the node. 10× probe: ~10 MΩ, 15 pF (much less loading). For RF circuits, use matched 50 Ω probes with active probes for impedance-sensitive measurements.','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-20','SMPS: Instability Under Load Transient','Hard','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','A switching power supply output oscillates (rings) when the load steps from 0 to full load. The regulation eventually settles but the transient ring is concerning. Cause:','{"choices": ["The inductor is saturating", "Insufficient control loop bandwidth — the error amplifier compensation is not fast enough to respond to the transient; output capacitance is insufficient for the transient energy storage", "Input voltage is wrong", "The feedback resistor divider is incorrect"], "correct": 1}'::jsonb,'Load transient ringing: (1) Low loop bandwidth → slow error amp response → output droops/overshoots before correcting. Fix: increase compensation bandwidth. (2) Insufficient output capacitance → energy storage can''t supply step current. Check Bode plot and output impedance.','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-21','Crosstalk Between PCB Traces','Hard','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','A high-speed digital signal on one PCB trace corrupts an adjacent analog signal trace. Mitigation strategies:','{"choices": ["Increase signal frequency", "Increase PCB thickness", "Separate digital and analog traces with ground guard traces, route parallel runs as short as possible, use orthogonal routing on adjacent layers, maintain 3× trace-width spacing", "Use thicker solder mask"], "correct": 2}'::jsonb,'Crosstalk: capacitive (field coupling) + inductive (mutual inductance). Mitigation: (1) 3W rule: trace spacing ≥ 3× width reduces 70% of near-end crosstalk. (2) Guard trace to GND between aggressor/victim. (3) Orthogonal routing on adjacent layers eliminates parallel runs.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-22','Functional Test: Component Substitution Risk','Hard','ECE','arena','select','ECE Troubleshooting','multiple_choice','During troubleshooting, a technician substitutes a "equivalent" capacitor (same capacitance, different type) and the circuit behaves differently. Most likely reason:','{"choices": ["The substitute capacitor has different tolerances", "Dielectric characteristics differ — e.g., substituting X5R ceramic for NP0: X5R has voltage coefficient (capacitance drops 30–50% at rated voltage) and temperature variation; NP0 is stable", "The physical size is wrong", "The color coding was misread"], "correct": 1}'::jsonb,'Ceramic capacitors: NP0/C0G → stable (temperature, voltage). X5R/X7R → ±15% temperature, −30% at rated voltage. Y5V → ±80/−20%! Substituting without checking dielectric type is a common source of mysterious failures in RF filters and regulators.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-23','Firmware: Stack Overflow Symptoms','Hard','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','An embedded system crashes unpredictably after extended operation. The crash address is different each time. Most likely cause:','{"choices": ["Watchdog timer is incorrectly configured", "Hardware failure in RAM", "Stack overflow — recursive functions or deep call chains overflow the stack into heap or global variable space, corrupting data and causing unpredictable crashes", "The MCU overheats"], "correct": 2}'::jsonb,'Random crash addresses = corrupted stack pointer or return address. Stack overflow is the primary suspect: a function''s local variables overflow stack into adjacent memory. Debug: (1) Enable stack canaries. (2) Check linker map for stack vs heap overlap. (3) Use RTOS stack high-water marks.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-24','Oscilloscope: Ground Loop Noise','Hard','ECE','arena','diagnose','ECE Troubleshooting','multiple_choice','When measuring a low-level signal (10 mV) with an oscilloscope, a large 50 Hz or 60 Hz hum appears. The most likely cause:','{"choices": ["The oscilloscope input impedance is too high", "Ground loop — the oscilloscope ground (earth via power cable) and the circuit ground form a loop; induced mains current flows through the measurement ground, adding noise to the signal", "The probe is incorrect type", "The signal frequency is too low"], "correct": 1}'::jsonb,'Ground loops are formed when the scope chassis ground (mains earth) and DUT ground are at different potentials, creating a current loop. Fix: (1) Battery-powered scope or floating measurement. (2) Break loop with isolation transformer. (3) Use differential probe.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ts-25','Systematic Debug: Divide and Conquer','Hard','ECE','arena','select','ECE Troubleshooting','multiple_choice','A complex embedded system with 5 subsystems is malfunctioning. Which debugging strategy finds the fault fastest on average?','{"choices": ["Test all subsystems simultaneously", "Replace all subsystems with known-good units", "Divide and conquer — binary halving of the system; test midpoint first; if OK narrow to second half, if fail narrow to first half. O(log n) vs O(n) for linear search", "Check the last-modified subsystem first"], "correct": 2}'::jsonb,'Divide and conquer (binary search): test the midpoint. If passes → fault in second half. If fails → fault in first half. Repeat. For 5 subsystems: 3 tests worst-case vs 5 for linear scan. For 100 subsystems: 7 tests vs 100. Always the most efficient isolation strategy.','{multiple_choice}'::text[],0.7) ON CONFLICT (slug) DO NOTHING;
